  // markdown.sublime-syntax
  '%YAML 1.2\n'
      '---\n'
      '# Old Brain Fix (obf-1036): written for this app, MIT OR Apache-2.0 as the app.\n'
      'name: Markdown\n'
      'scope: text.html.markdown\n'
      'file_extensions: [md, markdown, mdown, mkd]\n'
      '\n'
      'contexts:\n'
      '  main:\n'
      '    - match: \'^[ ]{0,3}```\'\n'
      '      push: fence_backticks\n'
      '    - match: \'^[ ]{0,3}~~~\'\n'
      '      push: fence_tildes\n'
      '    - match: \'^[ ]{0,3}#{1,6}(?=\\s|\$).*\'\n'
      '      scope: markup.heading.markdown\n'
      '    - match: \'^[ ]{0,3}=+[ \\t]*\$\'\n'
      '      scope: markup.heading.setext.markdown\n'
      '    - match: \'^[ ]{0,3}>.*\'\n'
      '      scope: markup.quote.markdown\n'
      '    - match: \'^[ ]{0,3}(\\[[^\\]\\n]+\\]:)[ \\t]*(\\S+)\'\n'
      '      captures:\n'
      '        1: entity.name.reference.markdown\n'
      '        2: markup.underline.link.markdown\n'
      '    - match: \'^\\s*([-+*]|\\d{1,9}[.)])(?=\\s)\'\n'
      '      captures:\n'
      '        1: keyword.other.list.markdown\n'
      '    - include: inline\n'
      '\n'
      '  inline:\n'
      '    - match: \'\\\\[\\\\`*_{}\\[\\]()#+\\-.!>|~<]\'\n'
      '      scope: constant.character.escape.markdown\n'
      '    - match: \'``.+?``\'\n'
      '      scope: markup.raw.inline.markdown\n'
      '    - match: \'`[^`\\n]+`\'\n'
      '      scope: markup.raw.inline.markdown\n'
      '    - match: \'<!--\'\n'
      '      push: html_comment\n'
      '    - match: \'<(?:https?|ftp|mailto):[^>\\s]+>\'\n'
      '      scope: markup.underline.link.markdown\n'
      '    - match: \'(\\]\\()([^)\\s]+)\'\n'
      '      captures:\n'
      '        2: markup.underline.link.markdown\n'
      '    - match: \'\\bhttps?://[^\\s<>()\\[\\]]+\'\n'
      '      scope: markup.underline.link.markdown\n'
      '\n'
      '  fence_backticks:\n'
      '    - meta_scope: markup.raw.block.markdown\n'
      '    - match: \'^[ ]{0,3}```+[ \\t]*\$\'\n'
      '      pop: true\n'
      '\n'
      '  fence_tildes:\n'
      '    - meta_scope: markup.raw.block.markdown\n'
      '    - match: \'^[ ]{0,3}~~~+[ \\t]*\$\'\n'
      '      pop: true\n'
      '\n'
      '  html_comment:\n'
      '    - meta_scope: comment.block.markdown\n'
      '    - match: \'-->\'\n'
      '      pop: true\n',
